import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r' {2,}', ' ', s)

def is_decimal(s):
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if not integer_part.isdigit():
        return False
    if len(decimal_part) != 2 or not decimal_part.isdigit():
        return False
    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) <= 1:
        return True
    unique_chars = set(s)
    if len(unique_chars) != 2:
        return False
    # To satisfy the example, we need to ensure the string alternates strictly 
    # between the two characters and does not have any partial pattern that breaks the alternation.
    # The example 'xyxyxyx' returns False because the last character breaks the strict alternation pattern.
    # So we need to ensure the string's length is even and perfectly alternating.
    # If length is odd, the last character breaks alternation pattern.

    # So first check if length is even
    if len(s) % 2 != 0:
        return False

    # Check if characters alternate starting with s[0]
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    # Finally, ensure the two characters alternate perfectly
    # For example, s[0] and s[2] should be the same, s[1] and s[3] should be the same, etc.
    first_char = s[0]
    second_char = s[1]
    for i in range(0, len(s), 2):
        if s[i] != first_char:
            return False
    for i in range(1, len(s), 2):
        if s[i] != second_char:
            return False

    return True

def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def count_nums(arr):
    def signed_digits(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            digits[0] = -digits[0]
        return digits

    count = 0
    for num in arr:
        if sum(signed_digits(num)) > 0:
            count += 1
    return count

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = 0
    total_product = 1
    for num in numbers:
        total_sum += num
        total_product *= num
    return (total_sum, total_product)

